/*
 * Split-skull jaw-drop animation. Each half shows its half of the skull.
 *
 * SPDX-License-Identifier: MIT
 */

#include <lvgl.h>
#include <zephyr/kernel.h>
#include <zmk/display.h>

/* Provided by skull_<half>_<rotation>.c (generated by gen_skull.py). */
extern const lv_img_dsc_t *skull_frames[];
extern const int skull_frame_count;

lv_obj_t *zmk_display_status_screen() {
    lv_obj_t *screen = lv_obj_create(NULL);

    /* Background matches palette index 0 of the frames so unlit areas stay dark. */
#if CONFIG_SKULL_OLED_INVERT
    lv_obj_set_style_bg_color(screen, lv_color_black(), LV_PART_MAIN);
#else
    lv_obj_set_style_bg_color(screen, lv_color_white(), LV_PART_MAIN);
#endif
    lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, LV_PART_MAIN);

    lv_obj_t *anim = lv_animimg_create(screen);
    lv_obj_set_pos(anim, 0, 0);
    lv_animimg_set_src(anim, (const void **)skull_frames, skull_frame_count);
    lv_animimg_set_duration(anim, CONFIG_SKULL_OLED_ANIMATION_MS);
    lv_animimg_set_repeat_count(anim, LV_ANIM_REPEAT_INFINITE);
    lv_animimg_start(anim);

    return screen;
}
